<script setup lang="ts">
import { computed, onBeforeUnmount, onMounted, reactive, ref } from 'vue'
import * as opsAPI from '@shared-api/admin/ops'
import type {
  AlertEvent, AlertRule, EmailNotificationConfig, OpsAccountAvailabilityStatsResponse, OpsAdvancedSettings,
  OpsAlertRuntimeSettings, OpsConcurrencyStatsResponse, OpsDashboardOverview, OpsErrorDetail, OpsErrorDistributionResponse,
  OpsErrorLog, OpsLatencyHistogramResponse, OpsMetricThresholds, OpsOpenAITokenStatsItem, OpsRequestDetail,
  OpsRuntimeLogConfig, OpsSystemLog, OpsSystemLogCleanupRequest, OpsSystemLogSinkHealth, OpsThroughputTrendPoint, OpsUserConcurrencyStatsResponse,
} from '@shared-api/admin/ops'
import ConsoleShell from '@/components/layout/ConsoleShell.vue'
import PageState from '@/components/base/PageState.vue'
import SurfaceDialog from '@/components/base/SurfaceDialog.vue'
import { DialogWidth } from '@/components/base/dialog'
import { ConfirmTone, useConfirmStore } from '@/stores/confirm'
import { useAppStore } from '@/stores/app'
import {
  AlertMetric, AlertOperator, AlertSeverity, GovernanceSortOrder, OpsErrorSourceTab, OpsQueryMode, OpsTimeRange,
  OpsWorkspaceTab, cloneData, formatCompactNumber, formatDuration, formatGovernanceDate, splitLines,
} from '@/features/admin/governance/model'

const app = useAppStore()
const confirm = useConfirmStore()
const activeTab = ref(OpsWorkspaceTab.OVERVIEW)
const loading = ref(true)
const secondaryLoading = ref(false)
const error = ref('')
const lastUpdated = ref('')
const autoRefresh = ref(true)
const liveSubscribed = ref(false)
const liveQPS = ref<number | null>(null)
const filters = reactive({ timeRange: OpsTimeRange.ONE_HOUR, platform: '', groupId: '', queryMode: OpsQueryMode.AUTO })
const overview = ref<OpsDashboardOverview | null>(null)
const throughput = ref<OpsThroughputTrendPoint[]>([])
const latency = ref<OpsLatencyHistogramResponse | null>(null)
const errorDistribution = ref<OpsErrorDistributionResponse | null>(null)
const concurrency = ref<OpsConcurrencyStatsResponse | null>(null)
const userConcurrency = ref<OpsUserConcurrencyStatsResponse | null>(null)
const availability = ref<OpsAccountAvailabilityStatsResponse | null>(null)
const tokenStats = ref<OpsOpenAITokenStatsItem[]>([])
const requests = ref<OpsRequestDetail[]>([])
const requestTotal = ref(0)
const requestPage = ref(1)
const requestPageSize = ref(20)
const requestFilters = reactive({ kind: 'all', userId: '', apiKeyId: '', accountId: '', model: '', requestId: '', q: '', minDuration: '', maxDuration: '', sort: 'created_at_desc' })
const errors = ref<OpsErrorLog[]>([])
const errorTotal = ref(0)
const errorPage = ref(1)
const errorPageSize = ref(20)
const errorSource = ref(OpsErrorSourceTab.REQUEST)
const errorFilters = reactive({ q: '', phase: '', category: '', owner: '', source: '', resolved: '', statusCodes: '', sortBy: 'created_at', sortOrder: GovernanceSortOrder.DESC })
const errorDetail = ref<OpsErrorDetail | null>(null)
const correlatedErrors = ref<OpsErrorDetail[]>([])
const errorDetailOpen = ref(false)
const rules = ref<AlertRule[]>([])
const events = ref<AlertEvent[]>([])
const ruleEditorOpen = ref(false)
const editingRuleId = ref<number | null>(null)
const ruleSaving = ref(false)
const ruleForm = reactive<AlertRule>({ name: '', description: '', enabled: true, metric_type: AlertMetric.ERROR_RATE, operator: AlertOperator.GREATER, threshold: 5, window_minutes: 5, sustained_minutes: 1, severity: AlertSeverity.WARNING, cooldown_minutes: 15, notify_email: true, filters: {} })
const alertDetail = ref<AlertEvent | null>(null)
const alertDetailOpen = ref(false)
const silenceUntil = ref('')
const silenceReason = ref('')
const systemLogs = ref<OpsSystemLog[]>([])
const systemLogTotal = ref(0)
const systemLogPage = ref(1)
const systemLogPageSize = ref(20)
const systemLogFilters = reactive({ timeRange: '1h', level: '', component: '', host: '', requestId: '', clientRequestId: '', userId: '', apiKeyId: '', accountId: '', platform: '', model: '', q: '' })
const sinkHealth = ref<OpsSystemLogSinkHealth | null>(null)
const logDetail = ref<OpsSystemLog | null>(null)
const logDetailOpen = ref(false)
const runtimeLog = ref<OpsRuntimeLogConfig | null>(null)
const emailConfig = ref<EmailNotificationConfig | null>(null)
const alertRuntime = ref<OpsAlertRuntimeSettings | null>(null)
const advanced = ref<OpsAdvancedSettings | null>(null)
const thresholds = ref<OpsMetricThresholds>({})
const alertRecipients = ref('')
const reportRecipients = ref('')
const settingsSaving = ref(false)
let controller: AbortController | null = null
let refreshTimer: number | null = null
let unsubscribeQPS: (() => void) | null = null

const maxThroughput = computed(() => Math.max(1, ...throughput.value.map((item) => item.request_count)))
const requestPages = computed(() => Math.max(1, Math.ceil(requestTotal.value / requestPageSize.value)))
const errorPages = computed(() => Math.max(1, Math.ceil(errorTotal.value / errorPageSize.value)))
const systemLogPages = computed(() => Math.max(1, Math.ceil(systemLogTotal.value / systemLogPageSize.value)))
const groupId = computed(() => filters.groupId ? Number(filters.groupId) : null)

function commonParams() {
  return { time_range: filters.timeRange, platform: filters.platform || undefined, group_id: groupId.value, mode: filters.queryMode }
}

async function loadOverview(silent = false): Promise<void> {
  controller?.abort(); controller = new AbortController(); const current = controller
  if (!silent) loading.value = true
  error.value = ''
  try {
    const [snapshotResult, latencyResult, distributionResult, concurrencyResult, userConcurrencyResult, availabilityResult, tokenResult] = await Promise.allSettled([
      opsAPI.getDashboardSnapshotV2(commonParams(), { signal: current.signal }),
      opsAPI.getLatencyHistogram(commonParams(), { signal: current.signal }),
      opsAPI.getErrorDistribution(commonParams(), { signal: current.signal }),
      opsAPI.getConcurrencyStats(filters.platform || undefined, groupId.value),
      opsAPI.getUserConcurrencyStats(),
      opsAPI.getAccountAvailabilityStats(filters.platform || undefined, groupId.value),
      opsAPI.getOpenAITokenStats({ time_range: '1h', platform: filters.platform || undefined, group_id: groupId.value, top_n: 12 }, { signal: current.signal }),
    ])
    if (snapshotResult.status === 'rejected') throw snapshotResult.reason
    overview.value = snapshotResult.value.overview
    throughput.value = snapshotResult.value.throughput_trend.points || []
    if (latencyResult.status === 'fulfilled') latency.value = latencyResult.value
    if (distributionResult.status === 'fulfilled') errorDistribution.value = distributionResult.value
    if (concurrencyResult.status === 'fulfilled') concurrency.value = concurrencyResult.value
    if (userConcurrencyResult.status === 'fulfilled') userConcurrency.value = userConcurrencyResult.value
    if (availabilityResult.status === 'fulfilled') availability.value = availabilityResult.value
    if (tokenResult.status === 'fulfilled') tokenStats.value = tokenResult.value.items || []
    lastUpdated.value = new Date().toISOString()
  } catch (caught) { if ((caught as { code?: string }).code !== 'ERR_CANCELED') error.value = (caught as { message?: string }).message || '实时运维概览加载失败' }
  finally { if (!silent && controller === current) loading.value = false }
}

function numberValue(value: string): number | undefined { const parsed = Number(value); return value && Number.isFinite(parsed) ? parsed : undefined }
async function loadRequests(): Promise<void> {
  secondaryLoading.value = true
  try { const response = await opsAPI.listRequestDetails({ ...commonParams(), kind: requestFilters.kind as 'all' | 'success' | 'error', page: requestPage.value, page_size: requestPageSize.value, user_id: numberValue(requestFilters.userId), api_key_id: numberValue(requestFilters.apiKeyId), account_id: numberValue(requestFilters.accountId), model: requestFilters.model || undefined, request_id: requestFilters.requestId || undefined, q: requestFilters.q || undefined, min_duration_ms: numberValue(requestFilters.minDuration), max_duration_ms: numberValue(requestFilters.maxDuration), sort: requestFilters.sort as 'created_at_desc' | 'duration_desc' }); requests.value = response.items || []; requestTotal.value = response.total || 0 }
  catch (caught) { app.showError((caught as { message?: string }).message || '请求明细加载失败') }
  finally { secondaryLoading.value = false }
}

async function loadErrors(): Promise<void> {
  secondaryLoading.value = true
  try {
    const method = errorSource.value === OpsErrorSourceTab.REQUEST ? opsAPI.listRequestErrors : opsAPI.listUpstreamErrors
    const response = await method({ page: errorPage.value, page_size: errorPageSize.value, time_range: filters.timeRange, platform: filters.platform || undefined, group_id: groupId.value, q: errorFilters.q || undefined, phase: errorFilters.phase || undefined, category: errorFilters.category || undefined, error_owner: errorFilters.owner || undefined, error_source: errorFilters.source || undefined, resolved: errorFilters.resolved || undefined, status_codes: errorFilters.statusCodes || undefined, view: 'all', sort_by: errorFilters.sortBy, sort_order: errorFilters.sortOrder })
    errors.value = response.items || []; errorTotal.value = response.total || 0
  } catch (caught) { app.showError((caught as { message?: string }).message || '错误日志加载失败') }
  finally { secondaryLoading.value = false }
}

async function openError(item: OpsErrorLog): Promise<void> {
  errorDetailOpen.value = true; errorDetail.value = null; correlatedErrors.value = []
  try {
    errorDetail.value = errorSource.value === OpsErrorSourceTab.REQUEST ? await opsAPI.getRequestErrorDetail(item.id) : await opsAPI.getUpstreamErrorDetail(item.id)
    if (errorSource.value === OpsErrorSourceTab.REQUEST) {
      const related = await opsAPI.listRequestErrorUpstreamErrors(item.id, { page: 1, page_size: 20 }, { include_detail: true })
      correlatedErrors.value = related.items || []
    }
  } catch (caught) { app.showError((caught as { message?: string }).message || '错误详情加载失败'); errorDetailOpen.value = false }
}

async function toggleResolved(item: OpsErrorLog): Promise<void> {
  try { if (errorSource.value === OpsErrorSourceTab.REQUEST) await opsAPI.updateRequestErrorResolved(item.id, !item.resolved); else await opsAPI.updateUpstreamErrorResolved(item.id, !item.resolved); app.showSuccess(item.resolved ? '错误已重新打开' : '错误已标记解决'); await loadErrors() }
  catch (caught) { app.showError((caught as { message?: string }).message || '错误状态更新失败') }
}

async function loadAlerts(): Promise<void> {
  secondaryLoading.value = true
  try { const result = await Promise.all([opsAPI.listAlertRules(), opsAPI.listAlertEvents({ limit: 100, time_range: filters.timeRange, platform: filters.platform || undefined, group_id: groupId.value || undefined })]); rules.value = result[0] || []; events.value = result[1] || [] }
  catch (caught) { app.showError((caught as { message?: string }).message || '告警数据加载失败') }
  finally { secondaryLoading.value = false }
}

function resetRule(): void { Object.assign(ruleForm, { id: undefined, name: '', description: '', enabled: true, metric_type: AlertMetric.ERROR_RATE, operator: AlertOperator.GREATER, threshold: 5, window_minutes: 5, sustained_minutes: 1, severity: AlertSeverity.WARNING, cooldown_minutes: 15, notify_email: true, filters: {} }); editingRuleId.value = null }
function openCreateRule(): void { resetRule(); ruleEditorOpen.value = true }
function openEditRule(item: AlertRule): void { Object.assign(ruleForm, cloneData(item)); editingRuleId.value = item.id || null; ruleEditorOpen.value = true }
async function saveRule(): Promise<void> { if (!ruleForm.name.trim()) { app.showError('规则名称不能为空'); return } ruleSaving.value = true; try { const payload = cloneData(ruleForm); if (editingRuleId.value) await opsAPI.updateAlertRule(editingRuleId.value, payload); else await opsAPI.createAlertRule(payload); ruleEditorOpen.value = false; app.showSuccess('告警规则已保存'); await loadAlerts() } catch (caught) { app.showError((caught as { message?: string }).message || '告警规则保存失败') } finally { ruleSaving.value = false } }
async function removeRule(item: AlertRule): Promise<void> { if (!item.id || !await confirm.ask({ title: '删除告警规则', message: `确认删除“${item.name}”？历史告警事件仍会保留。`, confirmText: '删除规则', tone: ConfirmTone.DANGER })) return; try { await opsAPI.deleteAlertRule(item.id); app.showSuccess('告警规则已删除'); await loadAlerts() } catch (caught) { app.showError((caught as { message?: string }).message || '规则删除失败') } }
async function openAlert(item: AlertEvent): Promise<void> { try { alertDetail.value = await opsAPI.getAlertEvent(item.id) } catch { alertDetail.value = item } silenceUntil.value = ''; silenceReason.value = ''; alertDetailOpen.value = true }
async function resolveAlert(): Promise<void> { if (!alertDetail.value) return; try { await opsAPI.updateAlertEventStatus(alertDetail.value.id, 'manual_resolved'); alertDetailOpen.value = false; app.showSuccess('告警已人工解决'); await loadAlerts() } catch (caught) { app.showError((caught as { message?: string }).message || '告警状态更新失败') } }
async function silenceAlert(): Promise<void> { if (!alertDetail.value || !silenceUntil.value) { app.showError('请选择静默截止时间'); return } try { await opsAPI.createAlertSilence({ rule_id: alertDetail.value.rule_id, platform: String(alertDetail.value.dimensions?.platform || filters.platform || ''), group_id: Number(alertDetail.value.dimensions?.group_id || 0) || null, until: new Date(silenceUntil.value).toISOString(), reason: silenceReason.value.trim() || undefined }); app.showSuccess('告警静默已创建'); silenceUntil.value = '' } catch (caught) { app.showError((caught as { message?: string }).message || '创建静默失败') } }

function systemLogQuery() { return { page: systemLogPage.value, page_size: systemLogPageSize.value, time_range: systemLogFilters.timeRange as '5m' | '30m' | '1h' | '6h' | '24h' | '7d' | '30d', level: systemLogFilters.level || undefined, component: systemLogFilters.component || undefined, host: systemLogFilters.host || undefined, request_id: systemLogFilters.requestId || undefined, client_request_id: systemLogFilters.clientRequestId || undefined, user_id: numberValue(systemLogFilters.userId) || null, api_key_id: numberValue(systemLogFilters.apiKeyId) || null, account_id: numberValue(systemLogFilters.accountId) || null, platform: systemLogFilters.platform || undefined, model: systemLogFilters.model || undefined, q: systemLogFilters.q || undefined } }
async function loadSystemLogs(): Promise<void> { secondaryLoading.value = true; try { const [response, health] = await Promise.all([opsAPI.listSystemLogs(systemLogQuery()), opsAPI.getSystemLogSinkHealth()]); systemLogs.value = response.items || []; systemLogTotal.value = response.total || 0; sinkHealth.value = health } catch (caught) { app.showError((caught as { message?: string }).message || '系统日志加载失败') } finally { secondaryLoading.value = false } }
function systemLogCleanupPayload(): OpsSystemLogCleanupRequest {
  return {
    level: systemLogFilters.level || undefined,
    component: systemLogFilters.component || undefined,
    host: systemLogFilters.host || undefined,
    request_id: systemLogFilters.requestId || undefined,
    client_request_id: systemLogFilters.clientRequestId || undefined,
    user_id: numberValue(systemLogFilters.userId) || null,
    api_key_id: numberValue(systemLogFilters.apiKeyId) || null,
    account_id: numberValue(systemLogFilters.accountId) || null,
    platform: systemLogFilters.platform || undefined,
    model: systemLogFilters.model || undefined,
    q: systemLogFilters.q || undefined,
  }
}
async function cleanupSystemLogs(): Promise<void> { if (!await confirm.ask({ title: '清理系统日志', message: '将按当前筛选条件删除系统日志，操作不可撤销。', confirmText: '确认清理', tone: ConfirmTone.DANGER })) return; try { const result = await opsAPI.cleanupSystemLogs(systemLogCleanupPayload()); app.showSuccess(`已清理 ${result.deleted} 条系统日志`); await loadSystemLogs() } catch (caught) { app.showError((caught as { message?: string }).message || '日志清理失败') } }
async function saveRuntimeLog(): Promise<void> { if (!runtimeLog.value) return; try { runtimeLog.value = await opsAPI.updateRuntimeLogConfig(cloneData(runtimeLog.value)); app.showSuccess('运行时日志配置已保存') } catch (caught) { app.showError((caught as { message?: string }).message || '日志配置保存失败') } }
async function resetRuntimeLogging(): Promise<void> { if (!await confirm.ask({ title: '恢复日志默认配置', message: '运行时日志级别、采样与保留期将恢复为后端默认值。', confirmText: '恢复默认', tone: ConfirmTone.DEFAULT })) return; try { runtimeLog.value = await opsAPI.resetRuntimeLogConfig(); app.showSuccess('日志配置已恢复默认') } catch (caught) { app.showError((caught as { message?: string }).message || '恢复失败') } }

async function loadSettings(): Promise<void> {
  secondaryLoading.value = true
  try {
    const [email, runtime, advancedValue, thresholdValue, logging] = await Promise.all([opsAPI.getEmailNotificationConfig(), opsAPI.getAlertRuntimeSettings(), opsAPI.getAdvancedSettings(), opsAPI.opsAPI.getMetricThresholds(), opsAPI.getRuntimeLogConfig()])
    emailConfig.value = email; alertRuntime.value = runtime; advanced.value = advancedValue; thresholds.value = thresholdValue; runtimeLog.value = logging
    alertRecipients.value = email.alert.recipients.join('\n'); reportRecipients.value = email.report.recipients.join('\n')
    autoRefresh.value = advancedValue.auto_refresh_enabled
    restartAutoRefresh()
  } catch (caught) { app.showError((caught as { message?: string }).message || '运维设置加载失败') }
  finally { secondaryLoading.value = false }
}

async function saveSettings(): Promise<void> {
  if (!emailConfig.value || !alertRuntime.value || !advanced.value) return
  settingsSaving.value = true
  try {
    emailConfig.value.alert.recipients = splitLines(alertRecipients.value); emailConfig.value.report.recipients = splitLines(reportRecipients.value)
    const [email, runtime, advancedValue] = await Promise.all([opsAPI.updateEmailNotificationConfig(cloneData(emailConfig.value)), opsAPI.updateAlertRuntimeSettings(cloneData(alertRuntime.value)), opsAPI.updateAdvancedSettings(cloneData(advanced.value)), opsAPI.opsAPI.updateMetricThresholds(cloneData(thresholds.value))])
    emailConfig.value = email; alertRuntime.value = runtime; advanced.value = advancedValue; autoRefresh.value = advancedValue.auto_refresh_enabled; restartAutoRefresh(); app.showSuccess('运维通知、阈值与运行设置已保存')
  } catch (caught) { app.showError((caught as { message?: string }).message || '运维设置保存失败') }
  finally { settingsSaving.value = false }
}

function switchTab(tab: OpsWorkspaceTab): void { activeTab.value = tab; if (tab === OpsWorkspaceTab.REQUESTS) void loadRequests(); if (tab === OpsWorkspaceTab.ERRORS) void loadErrors(); if (tab === OpsWorkspaceTab.ALERTS) void loadAlerts(); if (tab === OpsWorkspaceTab.LOGS) { void loadSystemLogs(); if (!runtimeLog.value) void opsAPI.getRuntimeLogConfig().then((value) => { runtimeLog.value = value }) } if (tab === OpsWorkspaceTab.SETTINGS) void loadSettings() }
function restartAutoRefresh(): void { if (refreshTimer) window.clearInterval(refreshTimer); refreshTimer = null; if (autoRefresh.value) refreshTimer = window.setInterval(() => { if (document.visibilityState === 'visible') void loadOverview(true) }, Math.max(10, advanced.value?.auto_refresh_interval_seconds || 30) * 1000) }
function toggleAutoRefresh(): void { autoRefresh.value = !autoRefresh.value; restartAutoRefresh() }
function toggleLiveSubscription(): void {
  if (unsubscribeQPS) { unsubscribeQPS(); unsubscribeQPS = null; liveSubscribed.value = false; liveQPS.value = null; return }
  try { unsubscribeQPS = opsAPI.subscribeQPS((message: unknown) => { const data = message as { qps?: number; current?: number; summary?: { qps?: { current?: number } } }; liveQPS.value = Number(data.qps ?? data.current ?? data.summary?.qps?.current ?? 0) }, { onStatusChange: (status) => { liveSubscribed.value = status === 'connected' || status === 'connecting' || status === 'reconnecting' } }); liveSubscribed.value = true; app.showSuccess('实时 QPS 订阅已开启') } catch (caught) { app.showError((caught as { message?: string }).message || '实时订阅连接失败') }
}

onMounted(() => { void loadOverview(); restartAutoRefresh() })
onBeforeUnmount(() => { controller?.abort(); if (refreshTimer) window.clearInterval(refreshTimer); unsubscribeQPS?.() })
</script>

<template>
  <ConsoleShell>
    <main class="resource-page">
      <header class="resource-page__heading"><div><span class="resource-eyebrow">Live Operations</span><h1>实时运维</h1><p>流量、并发、可用性、延迟、错误、告警与运行日志统一按平台和分组联动。</p></div><div class="resource-toolbar__actions"><button class="resource-button resource-button--secondary" :aria-pressed="autoRefresh" @click="toggleAutoRefresh">自动刷新 {{ autoRefresh ? '开' : '关' }}</button><button class="resource-button resource-button--secondary" :aria-pressed="liveSubscribed" @click="toggleLiveSubscription">实时 QPS {{ liveSubscribed ? '已订阅' : '订阅' }}</button><button class="resource-button" :disabled="loading" @click="loadOverview()">刷新</button></div></header>
      <section class="resource-toolbar"><div class="resource-toolbar__filters"><label>时间范围<select v-model="filters.timeRange" @change="loadOverview()"><option :value="OpsTimeRange.FIVE_MINUTES">5 分钟</option><option :value="OpsTimeRange.THIRTY_MINUTES">30 分钟</option><option :value="OpsTimeRange.ONE_HOUR">1 小时</option><option :value="OpsTimeRange.SIX_HOURS">6 小时</option><option :value="OpsTimeRange.ONE_DAY">24 小时</option></select></label><label>平台<input v-model="filters.platform" placeholder="全部平台" @keyup.enter="loadOverview()" /></label><label>分组 ID<input v-model="filters.groupId" inputmode="numeric" placeholder="全部分组" @keyup.enter="loadOverview()" /></label><label>查询模式<select v-model="filters.queryMode" @change="loadOverview()"><option :value="OpsQueryMode.AUTO">自动</option><option :value="OpsQueryMode.RAW">原始数据</option><option :value="OpsQueryMode.PREAGG">预聚合</option></select></label></div><span class="muted">更新 {{ formatGovernanceDate(lastUpdated) }}</span></section>
      <nav class="resource-tabs" aria-label="运维工作台"><button v-for="tab in [{ id: OpsWorkspaceTab.OVERVIEW, label: '实时概览' }, { id: OpsWorkspaceTab.REQUESTS, label: '请求明细' }, { id: OpsWorkspaceTab.ERRORS, label: '错误中心' }, { id: OpsWorkspaceTab.ALERTS, label: '告警' }, { id: OpsWorkspaceTab.LOGS, label: '系统日志' }, { id: OpsWorkspaceTab.SETTINGS, label: '通知与运行设置' }]" :key="tab.id" :aria-selected="activeTab === tab.id" @click="switchTab(tab.id)">{{ tab.label }}</button></nav>

      <PageState v-if="activeTab === OpsWorkspaceTab.OVERVIEW" :loading="loading" :error="error" @retry="loadOverview"><template v-if="overview"><section class="governance-kpis"><div><span>SLA</span><strong>{{ (overview.sla * (overview.sla <= 1 ? 100 : 1)).toFixed(2) }}%</strong></div><div><span>请求 / 成功</span><strong>{{ formatCompactNumber(overview.request_count_total) }} / {{ formatCompactNumber(overview.success_count) }}</strong></div><div><span>QPS 当前 / 峰值</span><strong>{{ (liveQPS ?? overview.qps.current).toFixed(2) }} / {{ overview.qps.peak.toFixed(2) }}</strong></div><div><span>TPS 当前 / 峰值</span><strong>{{ overview.tps.current.toFixed(1) }} / {{ overview.tps.peak.toFixed(1) }}</strong></div><div><span>错误率</span><strong>{{ (overview.error_rate * (overview.error_rate <= 1 ? 100 : 1)).toFixed(2) }}%</strong></div><div><span>上游错误率</span><strong>{{ (overview.upstream_error_rate * (overview.upstream_error_rate <= 1 ? 100 : 1)).toFixed(2) }}%</strong></div><div><span>延迟 P95</span><strong>{{ formatDuration(overview.duration.p95_ms) }}</strong></div><div><span>TTFT P99</span><strong>{{ formatDuration(overview.ttft.p99_ms) }}</strong></div></section><section class="governance-grid"><article class="governance-card"><header class="governance-card__header"><div><h2>吞吐趋势</h2><p>请求量、QPS、TPS 与账号切换。</p></div></header><div v-if="throughput.length" class="governance-chart"><div v-for="item in throughput" :key="item.bucket_start" :title="`${formatGovernanceDate(item.bucket_start)} · ${item.request_count} 请求 · QPS ${item.qps}`"><i :style="{ height: `${Math.max(4, item.request_count / maxThroughput * 160)}px` }"></i><span>{{ new Date(item.bucket_start).toLocaleTimeString('zh-CN', { hour: '2-digit', minute: '2-digit' }) }}</span></div></div></article><article class="governance-card"><header class="governance-card__header"><div><h2>延迟直方图</h2><p>{{ latency?.total_requests || 0 }} 个请求。</p></div></header><div class="governance-list"><article v-for="bucket in latency?.buckets || []" :key="bucket.range"><strong>{{ bucket.range }}</strong><span>{{ bucket.count }}</span></article></div></article><article class="governance-card"><header class="governance-card__header"><div><h2>错误分布</h2><p>区分 SLA 错误与业务限流。</p></div></header><div class="governance-list"><article v-for="item in errorDistribution?.items || []" :key="item.status_code"><div><strong>HTTP {{ item.status_code }}</strong><small>SLA {{ item.sla }} · 业务限流 {{ item.business_limited }}</small></div><strong>{{ item.total }}</strong></article></div></article><article class="governance-card"><header class="governance-card__header"><div><h2>系统资源</h2><p>数据库、Redis 与后台任务心跳。</p></div></header><dl class="governance-detail"><dt>健康分</dt><dd>{{ overview.health_score ?? '—' }}</dd><dt>CPU</dt><dd>{{ overview.system_metrics?.cpu_usage_percent ?? '—' }}%</dd><dt>内存</dt><dd>{{ overview.system_metrics?.memory_usage_percent ?? '—' }}%</dd><dt>DB / Redis</dt><dd>{{ overview.system_metrics?.db_ok ? '正常' : '异常' }} / {{ overview.system_metrics?.redis_ok ? '正常' : '异常' }}</dd><dt>Goroutine</dt><dd>{{ overview.system_metrics?.goroutine_count ?? '—' }}</dd><dt>并发队列</dt><dd>{{ overview.system_metrics?.concurrency_queue_depth ?? '—' }}</dd></dl></article></section><section class="governance-grid governance-grid--3"><article class="governance-card"><header class="governance-card__header"><div><h2>并发负载</h2><p>平台、分组、账号和用户队列。</p></div></header><div class="governance-list"><article v-for="item in Object.values(concurrency?.platform || {})" :key="item.platform"><div><strong>{{ item.platform }}</strong><small>{{ item.current_in_use }} / {{ item.max_capacity }} · 等待 {{ item.waiting_in_queue }}</small><div class="governance-meter"><i :style="{ width: `${Math.min(100, item.load_percentage)}%` }"></i></div></div><strong>{{ item.load_percentage.toFixed(0) }}%</strong></article><article v-for="item in Object.values(userConcurrency?.user || {}).slice(0, 5)" :key="item.user_id"><div><strong>{{ item.username || item.user_email }}</strong><small>用户 #{{ item.user_id }} · 等待 {{ item.waiting_in_queue }}</small></div><span>{{ item.current_in_use }} / {{ item.max_capacity }}</span></article></div></article><article class="governance-card"><header class="governance-card__header"><div><h2>账号可用性</h2><p>限流、过载和错误原因直接可见。</p></div></header><div class="governance-list"><article v-for="item in Object.values(availability?.account || {}).slice(0, 12)" :key="item.account_id"><div><strong>{{ item.account_name }}</strong><small>{{ item.platform }} · {{ item.group_name }}<template v-if="item.error_message"> · {{ item.error_message }}</template></small></div><span :class="['resource-status', item.is_available ? 'resource-status--active' : 'resource-status--error']">{{ item.status }}</span></article></div></article><article class="governance-card"><header class="governance-card__header"><div><h2>OpenAI Token 性能</h2><p>模型 TPS、首 token 和总输出。</p></div></header><div class="governance-list"><article v-for="item in tokenStats" :key="item.model"><div><strong>{{ item.model }}</strong><small>{{ item.request_count }} 请求 · 首 token {{ formatDuration(item.avg_first_token_ms) }}</small></div><div><strong>{{ Number(item.avg_tokens_per_sec || 0).toFixed(1) }} t/s</strong><small>{{ formatCompactNumber(item.total_output_tokens) }} 输出</small></div></article></div></article></section></template></PageState>

      <template v-else-if="activeTab === OpsWorkspaceTab.REQUESTS"><section class="governance-card"><div class="resource-form-grid resource-form-grid--4"><label>类型<select v-model="requestFilters.kind"><option value="all">全部</option><option value="success">成功</option><option value="error">错误</option></select></label><label>关键词<input v-model="requestFilters.q" /></label><label>请求 ID<input v-model="requestFilters.requestId" /></label><label>模型<input v-model="requestFilters.model" /></label><label>用户 ID<input v-model="requestFilters.userId" /></label><label>Key ID<input v-model="requestFilters.apiKeyId" /></label><label>账号 ID<input v-model="requestFilters.accountId" /></label><label>最短耗时 ms<input v-model="requestFilters.minDuration" type="number" /></label><label>最长耗时 ms<input v-model="requestFilters.maxDuration" type="number" /></label><label>排序<select v-model="requestFilters.sort"><option value="created_at_desc">时间倒序</option><option value="duration_desc">耗时倒序</option></select></label></div><button class="resource-button" @click="requestPage = 1; loadRequests()">查询请求</button></section><div v-if="secondaryLoading" class="page-state">正在加载请求…</div><div v-else class="resource-table"><table><thead><tr><th>时间</th><th>类型</th><th>平台 / 模型</th><th>耗时</th><th>状态</th><th>请求 ID</th><th>对象</th></tr></thead><tbody><tr v-for="item in requests" :key="`${item.created_at}-${item.request_id}`"><td>{{ formatGovernanceDate(item.created_at) }}</td><td><span :class="['resource-status', item.kind === 'success' ? 'resource-status--active' : 'resource-status--error']">{{ item.kind }}</span></td><td>{{ item.platform || '—' }}<small>{{ item.model || '—' }}</small></td><td>{{ formatDuration(item.duration_ms) }}</td><td>{{ item.status_code || '—' }}<small v-if="item.message">{{ item.message }}</small></td><td><code>{{ item.request_id }}</code></td><td>U{{ item.user_id || '—' }} · K{{ item.api_key_id || '—' }} · A{{ item.account_id || '—' }} · G{{ item.group_id || '—' }}</td></tr></tbody></table></div><footer class="resource-pagination"><span>共 {{ requestTotal }} 条 · 第 {{ requestPage }} / {{ requestPages }} 页</span><div class="resource-pagination__actions"><button class="resource-button resource-button--secondary" :disabled="requestPage <= 1" @click="requestPage--; loadRequests()">上一页</button><button class="resource-button resource-button--secondary" :disabled="requestPage >= requestPages" @click="requestPage++; loadRequests()">下一页</button></div></footer></template>

      <template v-else-if="activeTab === OpsWorkspaceTab.ERRORS"><section class="governance-card"><div class="governance-chip-list"><button :class="['governance-chip', errorSource === OpsErrorSourceTab.REQUEST && 'governance-chip--active']" @click="errorSource = OpsErrorSourceTab.REQUEST; errorPage = 1; loadErrors()">请求错误</button><button :class="['governance-chip', errorSource === OpsErrorSourceTab.UPSTREAM && 'governance-chip--active']" @click="errorSource = OpsErrorSourceTab.UPSTREAM; errorPage = 1; loadErrors()">上游错误</button></div><div class="resource-form-grid resource-form-grid--4"><label>关键词<input v-model="errorFilters.q" /></label><label>阶段<input v-model="errorFilters.phase" /></label><label>分类<input v-model="errorFilters.category" /></label><label>责任方<input v-model="errorFilters.owner" /></label><label>错误来源<input v-model="errorFilters.source" /></label><label>解决状态<select v-model="errorFilters.resolved"><option value="">全部</option><option value="false">待处理</option><option value="true">已解决</option></select></label><label>HTTP 状态码<input v-model="errorFilters.statusCodes" placeholder="429,500" /></label><label>排序<select v-model="errorFilters.sortBy"><option value="created_at">时间</option><option value="model">模型</option><option value="status_code">状态码</option></select></label></div><button class="resource-button" @click="errorPage = 1; loadErrors()">查询错误</button></section><div v-if="secondaryLoading" class="page-state">正在加载错误…</div><div v-else class="resource-table"><table><thead><tr><th>时间</th><th>错误</th><th>对象</th><th>平台 / 模型</th><th>状态</th><th>操作</th></tr></thead><tbody><tr v-for="item in errors" :key="item.id"><td>{{ formatGovernanceDate(item.created_at) }}<small><code>{{ item.request_id }}</code></small></td><td><strong>{{ item.message }}</strong><small>{{ item.phase }} · {{ item.type }} · {{ item.error_owner }}</small></td><td>{{ item.user_email || `U${item.user_id}` }}<small>{{ item.api_key_name || `K${item.api_key_id}` }} · {{ item.account_name || `A${item.account_id}` }}</small></td><td>{{ item.platform }}<small>{{ item.model }} · HTTP {{ item.status_code }}</small></td><td><span :class="['resource-status', item.resolved ? 'resource-status--active' : 'resource-status--error']">{{ item.resolved ? '已解决' : '待处理' }}</span></td><td><div class="resource-inline-actions"><button class="resource-link" @click="openError(item)">详情</button><button class="resource-link" @click="toggleResolved(item)">{{ item.resolved ? '重新打开' : '标记解决' }}</button></div></td></tr></tbody></table></div><footer class="resource-pagination"><span>共 {{ errorTotal }} 条 · 第 {{ errorPage }} / {{ errorPages }} 页</span><div class="resource-pagination__actions"><button class="resource-button resource-button--secondary" :disabled="errorPage <= 1" @click="errorPage--; loadErrors()">上一页</button><button class="resource-button resource-button--secondary" :disabled="errorPage >= errorPages" @click="errorPage++; loadErrors()">下一页</button></div></footer></template>

      <template v-else-if="activeTab === OpsWorkspaceTab.ALERTS"><div class="resource-toolbar"><strong>告警规则与事件</strong><button class="resource-button" @click="openCreateRule">创建规则</button></div><div v-if="secondaryLoading" class="page-state">正在加载告警…</div><section v-else class="governance-grid"><article class="governance-card"><header class="governance-card__header"><div><h2>规则</h2><p>持续时间、冷却、严重性与通知独立配置。</p></div></header><div class="governance-list"><article v-for="item in rules" :key="item.id"><div><strong>{{ item.name }}</strong><small>{{ item.metric_type }} {{ item.operator }} {{ item.threshold }} · {{ item.window_minutes }} 分钟窗口 · 持续 {{ item.sustained_minutes }} 分钟</small></div><div class="resource-inline-actions"><span :class="['resource-status', item.enabled ? 'resource-status--active' : '']">{{ item.enabled ? item.severity : '停用' }}</span><button class="resource-link" @click="openEditRule(item)">编辑</button><button class="resource-link resource-link--danger" @click="removeRule(item)">删除</button></div></article></div></article><article class="governance-card"><header class="governance-card__header"><div><h2>事件</h2><p>查看详情、人工解决并按维度静默。</p></div></header><div class="governance-list"><article v-for="item in events" :key="item.id"><button class="resource-link" @click="openAlert(item)">{{ item.title || `告警 #${item.id}` }}<small>{{ formatGovernanceDate(item.fired_at) }} · 规则 #{{ item.rule_id }}</small></button><span :class="['resource-status', item.status === 'firing' ? 'resource-status--error' : 'resource-status--active']">{{ item.severity }} · {{ item.status }}</span></article></div></article></section></template>

      <template v-else-if="activeTab === OpsWorkspaceTab.LOGS"><section v-if="sinkHealth" class="resource-summary"><div><span>写入队列</span><strong>{{ sinkHealth.queue_depth }} / {{ sinkHealth.queue_capacity }}</strong></div><div><span>已写入</span><strong>{{ formatCompactNumber(sinkHealth.written_count) }}</strong></div><div><span>丢弃 / 失败</span><strong>{{ sinkHealth.dropped_count }} / {{ sinkHealth.write_failed_count }}</strong></div><div><span>平均写延迟</span><strong>{{ formatDuration(sinkHealth.avg_write_delay_ms) }}</strong></div></section><section class="governance-card"><div class="resource-form-grid resource-form-grid--4"><label>范围<select v-model="systemLogFilters.timeRange"><option value="5m">5 分钟</option><option value="1h">1 小时</option><option value="24h">24 小时</option><option value="7d">7 天</option><option value="30d">30 天</option></select></label><label>级别<select v-model="systemLogFilters.level"><option value="">全部</option><option>debug</option><option>info</option><option>warn</option><option>error</option></select></label><label>组件<input v-model="systemLogFilters.component" /></label><label>主机<input v-model="systemLogFilters.host" /></label><label>请求 ID<input v-model="systemLogFilters.requestId" /></label><label>客户端请求 ID<input v-model="systemLogFilters.clientRequestId" /></label><label>用户 ID<input v-model="systemLogFilters.userId" /></label><label>Key ID<input v-model="systemLogFilters.apiKeyId" /></label><label>账号 ID<input v-model="systemLogFilters.accountId" /></label><label>平台<input v-model="systemLogFilters.platform" /></label><label>模型<input v-model="systemLogFilters.model" /></label><label>关键词<input v-model="systemLogFilters.q" /></label></div><div class="resource-inline-actions"><button class="resource-button" @click="systemLogPage = 1; loadSystemLogs()">查询日志</button><button class="resource-button resource-button--danger" @click="cleanupSystemLogs">按当前条件清理</button></div></section><div v-if="secondaryLoading" class="page-state">正在加载系统日志…</div><div v-else class="resource-table"><table><thead><tr><th>时间</th><th>级别</th><th>组件 / 主机</th><th>消息</th><th>请求</th><th>对象</th><th>操作</th></tr></thead><tbody><tr v-for="item in systemLogs" :key="item.id"><td>{{ formatGovernanceDate(item.created_at) }}</td><td><span :class="['resource-status', item.level === 'error' ? 'resource-status--error' : item.level === 'warn' ? 'resource-status--degraded' : '']">{{ item.level }}</span></td><td>{{ item.component }}<small>{{ item.host }}</small></td><td>{{ item.message }}</td><td><code>{{ item.request_id || item.client_request_id || '—' }}</code></td><td>U{{ item.user_id || '—' }} · K{{ item.api_key_id || '—' }} · A{{ item.account_id || '—' }}</td><td><button class="resource-link" @click="logDetail = item; logDetailOpen = true">详情</button></td></tr></tbody></table></div><footer class="resource-pagination"><span>共 {{ systemLogTotal }} 条 · 第 {{ systemLogPage }} / {{ systemLogPages }} 页</span><div class="resource-pagination__actions"><button class="resource-button resource-button--secondary" :disabled="systemLogPage <= 1" @click="systemLogPage--; loadSystemLogs()">上一页</button><button class="resource-button resource-button--secondary" :disabled="systemLogPage >= systemLogPages" @click="systemLogPage++; loadSystemLogs()">下一页</button></div></footer><article v-if="runtimeLog" class="governance-card"><header class="governance-card__header"><div><h2>运行时日志配置</h2><p>立即生效，无需修改部署文件。</p></div><div class="resource-inline-actions"><button class="resource-button resource-button--secondary" @click="resetRuntimeLogging">恢复默认</button><button class="resource-button" @click="saveRuntimeLog">保存日志配置</button></div></header><div class="resource-form-grid resource-form-grid--4"><label>级别<select v-model="runtimeLog.level"><option>debug</option><option>info</option><option>warn</option><option>error</option></select></label><label>堆栈级别<select v-model="runtimeLog.stacktrace_level"><option value="none">none</option><option value="error">error</option><option value="fatal">fatal</option></select></label><label>初始采样<input v-model.number="runtimeLog.sampling_initial" type="number" min="1" /></label><label>后续采样<input v-model.number="runtimeLog.sampling_thereafter" type="number" min="1" /></label><label>保留天数<input v-model.number="runtimeLog.retention_days" type="number" min="1" /></label><label class="resource-check"><input v-model="runtimeLog.enable_sampling" type="checkbox" />启用采样</label><label class="resource-check"><input v-model="runtimeLog.caller" type="checkbox" />记录调用位置</label></div></article></template>

      <template v-else><div v-if="secondaryLoading" class="page-state">正在加载设置…</div><template v-else-if="emailConfig && alertRuntime && advanced"><section class="governance-grid"><article class="governance-card"><header class="governance-card__header"><div><h2>告警邮件</h2><p>收件人每行一个，支持严重性门槛、限频和合并窗口。</p></div></header><div class="resource-form-stack"><label class="resource-check"><input v-model="emailConfig.alert.enabled" type="checkbox" />启用告警邮件</label><label>收件人<textarea v-model="alertRecipients" rows="4" /></label><label>最低严重性<select v-model="emailConfig.alert.min_severity"><option value="">全部</option><option :value="AlertSeverity.INFO">Info</option><option :value="AlertSeverity.WARNING">Warning</option><option :value="AlertSeverity.CRITICAL">Critical</option></select></label><div class="resource-form-grid"><label>每小时限额<input v-model.number="emailConfig.alert.rate_limit_per_hour" type="number" /></label><label>合并窗口秒<input v-model.number="emailConfig.alert.batching_window_seconds" type="number" /></label></div><label class="resource-check"><input v-model="emailConfig.alert.include_resolved_alerts" type="checkbox" />包含已解决通知</label></div></article><article class="governance-card"><header class="governance-card__header"><div><h2>运营报告</h2><p>日报、周报、错误摘要和账号健康报告独立排期。</p></div></header><div class="resource-form-stack"><label class="resource-check"><input v-model="emailConfig.report.enabled" type="checkbox" />启用运营报告</label><label>收件人<textarea v-model="reportRecipients" rows="4" /></label><div class="resource-form-grid"><label class="resource-check"><input v-model="emailConfig.report.daily_summary_enabled" type="checkbox" />日报</label><label>日报 Cron<input v-model="emailConfig.report.daily_summary_schedule" /></label><label class="resource-check"><input v-model="emailConfig.report.weekly_summary_enabled" type="checkbox" />周报</label><label>周报 Cron<input v-model="emailConfig.report.weekly_summary_schedule" /></label><label class="resource-check"><input v-model="emailConfig.report.error_digest_enabled" type="checkbox" />错误摘要</label><label>错误摘要 Cron<input v-model="emailConfig.report.error_digest_schedule" /></label><label>摘要最小错误数<input v-model.number="emailConfig.report.error_digest_min_count" type="number" /></label><label class="resource-check"><input v-model="emailConfig.report.account_health_enabled" type="checkbox" />账号健康报告</label><label>健康报告 Cron<input v-model="emailConfig.report.account_health_schedule" /></label><label>错误率门槛<input v-model.number="emailConfig.report.account_health_error_rate_threshold" type="number" step="0.01" /></label></div></div></article><article class="governance-card"><header class="governance-card__header"><div><h2>告警运行时</h2><p>评估频率、分布式锁与全局静默。</p></div></header><div class="resource-form-stack"><label>评估间隔秒<input v-model.number="alertRuntime.evaluation_interval_seconds" type="number" min="1" /></label><label class="resource-check"><input v-model="alertRuntime.distributed_lock.enabled" type="checkbox" />启用分布式锁</label><div class="resource-form-grid"><label>锁 Key<input v-model="alertRuntime.distributed_lock.key" /></label><label>TTL 秒<input v-model.number="alertRuntime.distributed_lock.ttl_seconds" type="number" /></label></div><label class="resource-check"><input v-model="alertRuntime.silencing.enabled" type="checkbox" />启用全局静默</label><label>全局静默至<input v-model="alertRuntime.silencing.global_until_rfc3339" /></label><label>静默原因<input v-model="alertRuntime.silencing.global_reason" /></label></div></article><article class="governance-card"><header class="governance-card__header"><div><h2>指标阈值</h2><p>控制概览的风险提示颜色。</p></div></header><div class="resource-form-stack"><label>SLA 最低 %<input v-model.number="thresholds.sla_percent_min" type="number" step="0.01" /></label><label>TTFT P99 最大 ms<input v-model.number="thresholds.ttft_p99_ms_max" type="number" /></label><label>请求错误率最大 %<input v-model.number="thresholds.request_error_rate_percent_max" type="number" step="0.01" /></label><label>上游错误率最大 %<input v-model.number="thresholds.upstream_error_rate_percent_max" type="number" step="0.01" /></label></div></article></section><article class="governance-card"><header class="governance-card__header"><div><h2>高级运行设置</h2><p>数据保留、预聚合、OpenAI 限额自动暂停、错误排除与页面刷新行为。</p></div></header><div class="resource-form-grid resource-form-grid--4"><label class="resource-check"><input v-model="advanced.data_retention.cleanup_enabled" type="checkbox" />定时清理</label><label>清理 Cron<input v-model="advanced.data_retention.cleanup_schedule" /></label><label>错误日志保留天<input v-model.number="advanced.data_retention.error_log_retention_days" type="number" /></label><label>分钟指标保留天<input v-model.number="advanced.data_retention.minute_metrics_retention_days" type="number" /></label><label>小时指标保留天<input v-model.number="advanced.data_retention.hourly_metrics_retention_days" type="number" /></label><label class="resource-check"><input v-model="advanced.aggregation.aggregation_enabled" type="checkbox" />启用预聚合</label><label>OpenAI 5h 自动暂停阈值<input v-model.number="advanced.openai_account_quota_auto_pause.default_threshold_5h" type="number" min="0" max="1" step="0.01" /></label><label>OpenAI 7d 自动暂停阈值<input v-model.number="advanced.openai_account_quota_auto_pause.default_threshold_7d" type="number" min="0" max="1" step="0.01" /></label><label class="resource-check"><input v-model="advanced.ignore_count_tokens_errors" type="checkbox" />忽略 count_tokens 错误</label><label class="resource-check"><input v-model="advanced.ignore_context_canceled" type="checkbox" />忽略 context canceled</label><label class="resource-check"><input v-model="advanced.ignore_no_available_accounts" type="checkbox" />忽略无可用账号</label><label class="resource-check"><input v-model="advanced.ignore_invalid_api_key_errors" type="checkbox" />忽略无效 Key</label><label class="resource-check"><input v-model="advanced.ignore_insufficient_balance_errors" type="checkbox" />忽略余额不足</label><label class="resource-check"><input v-model="advanced.display_openai_token_stats" type="checkbox" />显示 OpenAI token 统计</label><label class="resource-check"><input v-model="advanced.display_alert_events" type="checkbox" />显示告警事件</label><label class="resource-check"><input v-model="advanced.auto_refresh_enabled" type="checkbox" />自动刷新</label><label>刷新间隔秒<input v-model.number="advanced.auto_refresh_interval_seconds" type="number" min="10" /></label></div></article><div class="governance-sticky-actions"><span>保存会同时更新通知、阈值、运行时和高级设置。</span><button class="resource-button" :disabled="settingsSaving" @click="saveSettings">{{ settingsSaving ? '保存中…' : '保存全部运维设置' }}</button></div></template></template>
    </main>

    <SurfaceDialog :show="errorDetailOpen" title="错误事件详情" description="请求错误会同时列出其关联上游错误链。" :width="DialogWidth.WIDE" @close="errorDetailOpen = false"><div v-if="!errorDetail" class="page-state">加载详情…</div><template v-else><dl class="governance-detail"><dt>消息</dt><dd>{{ errorDetail.message }}</dd><dt>分类</dt><dd>{{ errorDetail.phase }} · {{ errorDetail.type }} · {{ errorDetail.error_owner }} · {{ errorDetail.error_source }}</dd><dt>状态</dt><dd>{{ errorDetail.status_code }} / 上游 {{ errorDetail.upstream_status_code || '—' }}</dd><dt>模型</dt><dd>{{ errorDetail.requested_model || errorDetail.model }} → {{ errorDetail.upstream_model || '—' }}</dd><dt>对象</dt><dd>{{ errorDetail.user_email }} · {{ errorDetail.api_key_name }} · {{ errorDetail.account_name }} · {{ errorDetail.group_name }}</dd><dt>耗时</dt><dd>认证 {{ formatDuration(errorDetail.auth_latency_ms) }} · 路由 {{ formatDuration(errorDetail.routing_latency_ms) }} · 上游 {{ formatDuration(errorDetail.upstream_latency_ms) }} · 响应 {{ formatDuration(errorDetail.response_latency_ms) }}</dd></dl><pre class="resource-code">{{ errorDetail.error_body || errorDetail.upstream_error_detail || errorDetail.upstream_error_message || '无错误体' }}</pre><section v-if="correlatedErrors.length"><h3>关联上游错误</h3><div class="governance-list"><article v-for="item in correlatedErrors" :key="item.id"><div><strong>{{ item.message }}</strong><small>{{ item.status_code }} · {{ item.account_name }} · {{ item.upstream_endpoint }}</small></div><span>{{ formatGovernanceDate(item.created_at) }}</span></article></div></section></template></SurfaceDialog>
    <SurfaceDialog :show="ruleEditorOpen" :title="editingRuleId ? '编辑告警规则' : '创建告警规则'" description="当指标在窗口内持续满足条件时触发，冷却期内不重复通知。" :width="DialogWidth.WIDE" @close="ruleEditorOpen = false"><form id="alert-rule-form" class="resource-form-stack" @submit.prevent="saveRule"><div class="resource-form-grid"><label>名称 *<input v-model="ruleForm.name" required /></label><label>说明<input v-model="ruleForm.description" /></label><label>指标<select v-model="ruleForm.metric_type"><option v-for="metric in Object.values(AlertMetric)" :key="metric" :value="metric">{{ metric }}</option></select></label><label>运算符<select v-model="ruleForm.operator"><option v-for="operator in Object.values(AlertOperator)" :key="operator" :value="operator">{{ operator }}</option></select></label><label>阈值<input v-model.number="ruleForm.threshold" type="number" step="0.01" /></label><label>严重性<select v-model="ruleForm.severity"><option v-for="severity in Object.values(AlertSeverity)" :key="severity" :value="severity">{{ severity }}</option></select></label><label>窗口分钟<input v-model.number="ruleForm.window_minutes" type="number" min="1" /></label><label>持续分钟<input v-model.number="ruleForm.sustained_minutes" type="number" min="1" /></label><label>冷却分钟<input v-model.number="ruleForm.cooldown_minutes" type="number" min="0" /></label><label class="resource-check"><input v-model="ruleForm.enabled" type="checkbox" />启用规则</label><label class="resource-check"><input v-model="ruleForm.notify_email" type="checkbox" />邮件通知</label></div><label>维度筛选 JSON<textarea :value="JSON.stringify(ruleForm.filters || {}, null, 2)" rows="4" @change="ruleForm.filters = JSON.parse(($event.target as HTMLTextAreaElement).value || '{}')" /></label></form><template #footer><button class="button button--secondary" @click="ruleEditorOpen = false">取消</button><button type="submit" form="alert-rule-form" class="button button--primary" :disabled="ruleSaving">{{ ruleSaving ? '保存中…' : '保存规则' }}</button></template></SurfaceDialog>
    <SurfaceDialog :show="alertDetailOpen" :title="alertDetail?.title || '告警详情'" :description="alertDetail ? `${alertDetail.severity} · ${alertDetail.status} · ${formatGovernanceDate(alertDetail.fired_at)}` : ''" :width="DialogWidth.STANDARD" @close="alertDetailOpen = false"><template v-if="alertDetail"><dl class="governance-detail"><dt>规则</dt><dd>#{{ alertDetail.rule_id }}</dd><dt>指标 / 阈值</dt><dd>{{ alertDetail.metric_value ?? '—' }} / {{ alertDetail.threshold_value ?? '—' }}</dd><dt>邮件</dt><dd>{{ alertDetail.email_sent ? '已发送' : '未发送' }}</dd><dt>维度</dt><dd><pre class="resource-code">{{ JSON.stringify(alertDetail.dimensions || {}, null, 2) }}</pre></dd></dl><div class="governance-danger-zone"><h3>事件操作</h3><div class="resource-form-grid"><label>静默至<input v-model="silenceUntil" type="datetime-local" /></label><label>静默原因<input v-model="silenceReason" /></label></div><div class="resource-inline-actions"><button class="resource-button resource-button--secondary" @click="silenceAlert">创建静默</button><button v-if="alertDetail.status === 'firing'" class="resource-button" @click="resolveAlert">人工解决</button></div></div></template></SurfaceDialog>
    <SurfaceDialog :show="logDetailOpen" title="系统日志详情" description="原始扩展上下文保持结构化展示。" :width="DialogWidth.WIDE" @close="logDetailOpen = false"><template v-if="logDetail"><dl class="governance-detail"><dt>时间</dt><dd>{{ formatGovernanceDate(logDetail.created_at) }}</dd><dt>级别</dt><dd>{{ logDetail.level }}</dd><dt>组件 / 主机</dt><dd>{{ logDetail.component }} / {{ logDetail.host }}</dd><dt>消息</dt><dd>{{ logDetail.message }}</dd><dt>请求</dt><dd>{{ logDetail.request_id || '—' }} / {{ logDetail.client_request_id || '—' }}</dd><dt>对象</dt><dd>U{{ logDetail.user_id || '—' }} · K{{ logDetail.api_key_id || '—' }} · A{{ logDetail.account_id || '—' }}</dd></dl><pre class="resource-code">{{ JSON.stringify(logDetail.extra || {}, null, 2) }}</pre></template></SurfaceDialog>
  </ConsoleShell>
</template>

